import Testing
import UIKit
import Models

/// Verifies the bundled screen masks for every device frame.
///
/// Masks are generated by `Scripts/generate_screen_masks.py`. These tests rebuild each mask from the frame artwork
/// with an independent flood fill, so a missing or stale mask fails the suite.
struct ScreenMaskTests {
    /// One entry per frame, in the device's default color. Every orientation and view counts as its own frame.
    private static let frames: [DeviceInfo] = {
        var seen = Set<String>()

        // Include each device's alternate views, which have their own frames and masks.
        return DeviceInfo.all()
            .flatMap { device in [device] + device.views.dropFirst().map { device.withView($0) } }
            .filter { seen.insert($0.deviceFrame).inserted }
    }()

    /// Frames whose bezel has no enclosed screen to mask. None today.
    private static let framesWithoutMask: Set<String> = []

    private static let framesWithMask = frames.filter { !framesWithoutMask.contains($0.deviceFrame) }

    /// Each frame in its default color, plus its last color when the device has several, so alternate colors
    /// are composited too.
    private static let compositeCases: [DeviceInfo] = framesWithMask.flatMap { device -> [DeviceInfo] in
        guard device.hasColorOptions, let last = device.colors.last else { return [device] }
        return [device, device.withColor(last)]
    }

    @Test("Every frame has a bundled mask sized to its screen")
    func everyFrameHasMask() throws {
        #expect(!Self.frames.isEmpty)

        for device in Self.frames {
            if Self.framesWithoutMask.contains(device.deviceFrame) {
                #expect(device.screenMask == nil, "\(device.deviceFrame) should not have a mask")
            } else {
                let mask = try #require(device.screenMask, "Missing mask for \(device.deviceFrame)")

                #expect(CGSize(width: mask.width, height: mask.height) == device.screenSize, "\(device.deviceFrame)")
            }
        }
    }

    @Test("Bundled masks cover the screen of every color", arguments: framesWithMask)
    func bundledMaskMatchesFrame(device: DeviceInfo) throws {
        let bundled = grayPixels(of: try #require(device.screenMask))
        let colors: [String?] = device.hasColorOptions ? device.colors : [nil]
        var union = [UInt8](repeating: 0, count: bundled.count)

        for color in colors {
            let variant = color.map { device.withColor($0) } ?? device
            let reference = ReferenceMask(frame: try #require(variant.frameImage), seed: screenCenter(of: variant))

            #expect(reference.hasEnclosedScreen, "\(variant.deviceFrame)")

            let cropped = reference.croppedPixels(offset: variant.offSet, size: device.screenSize)

            for index in cropped.indices where cropped[index] == 255 { union[index] = 255 }
        }

        // One mask is shared by every color, so it is the union of each color's screen.
        #expect(union == bundled, "\(device.deviceFrame)")
    }

    @Test("Framed screenshot fills the whole screen and never leaks outside the device", arguments: compositeCases)
    func framedScreenshotHasNoLeakOrGap(device: DeviceInfo) throws {
        let frame = try #require(device.frameImage, "Missing frame \(device.deviceFrame)")
        let reference = ReferenceMask(frame: frame, seed: screenCenter(of: device))
        let framed = try #require(device.framed(using: solidImage(color: .red, size: device.inputSize)))
        let framedPixels = rgbaPixels(of: framed)
        let framePixels = rgbaPixels(of: frame)
        let screen = CGRect(origin: device.offSet, size: device.screenSize)

        #expect(framedPixels.count == framePixels.count)

        var leaks = 0
        var gaps = 0

        for index in 0..<reference.fullPixels.count where framePixels[index * 4 + 3] == 0 {
            let framedAlpha = framedPixels[index * 4 + 3]

            if reference.fullPixels[index] == 0 {
                // Outside the screen opening: nothing should be drawn.
                if framedAlpha != 0 { leaks += 1 }
            } else if screen.contains(CGPoint(x: index % reference.width, y: index / reference.width)) {
                // Inside the screen opening: the screenshot must cover it fully.
                if framedAlpha != 255 || framedPixels[index * 4] != 255 { gaps += 1 }
            }
        }

        #expect(leaks == 0, "\(device.deviceFrame)")
        #expect(gaps == 0, "\(device.deviceFrame)")
    }

    // MARK: - Helpers

    /// A point in the middle of the device's screen opening, where the flood fill starts.
    private func screenCenter(of device: DeviceInfo) -> (x: Int, y: Int) {
        (Int(device.offSet.x + device.screenSize.width / 2), Int(device.offSet.y + device.screenSize.height / 2))
    }

    private func solidImage(color: UIColor, size: CGSize) -> UIImage {
        let format = UIGraphicsImageRendererFormat()
        format.scale = 1
        return UIGraphicsImageRenderer(size: size, format: format).image { context in
            color.setFill()
            context.fill(CGRect(origin: .zero, size: size))
        }
    }

    private func grayPixels(of image: CGImage) -> [UInt8] {
        var pixels = [UInt8](repeating: 0, count: image.width * image.height)
        pixels.withUnsafeMutableBytes { buffer in
            let context = CGContext(
                data: buffer.baseAddress,
                width: image.width,
                height: image.height,
                bitsPerComponent: 8,
                bytesPerRow: image.width,
                space: CGColorSpaceCreateDeviceGray(),
                bitmapInfo: CGImageAlphaInfo.none.rawValue
            )
            context?.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))
        }
        return pixels
    }
}

/// The screen mask of a frame, built by flood-filling every pixel reachable from a point inside the screen that is not bezel.
/// A pixel with alpha of at least `bezelAlpha` counts as bezel, because some frames use 250 to 254 instead of 255.
private struct ReferenceMask {
    static let bezelAlpha: UInt8 = 250

    let width: Int
    let height: Int
    /// 255 for screen, 0 for everything else, covering the whole frame.
    let fullPixels: [UInt8]
    /// Whether the flood fill found a screen that never reaches the edge of the frame.
    let hasEnclosedScreen: Bool

    init(frame: UIImage, seed: (x: Int, y: Int)) {
        let pixels = rgbaPixels(of: frame)
        let width = Int(frame.size.width)
        let height = Int(frame.size.height)
        var mask = [UInt8](repeating: 0, count: width * height)
        let bezelAlpha = Self.bezelAlpha

        pixels.withUnsafeBufferPointer { pixels in
            mask.withUnsafeMutableBufferPointer { mask in
                // A pixel is fillable when it is not bezel and has not been filled yet.
                @inline(__always) func isFillable(_ x: Int, _ y: Int) -> Bool {
                    let index = y * width + x
                    return mask[index] == 0 && pixels[index * 4 + 3] < bezelAlpha
                }

                var seeds = [(x: Int, y: Int)]()
                seeds.append(seed)

                while let seed = seeds.popLast() {
                    guard isFillable(seed.x, seed.y) else { continue }

                    var left = seed.x
                    while left > 0, isFillable(left - 1, seed.y) { left -= 1 }
                    var right = seed.x
                    while right < width - 1, isFillable(right + 1, seed.y) { right += 1 }

                    for x in left...right { mask[seed.y * width + x] = 255 }

                    for y in [seed.y - 1, seed.y + 1] where y >= 0 && y < height {
                        var x = left
                        while x <= right {
                            if isFillable(x, y) {
                                seeds.append((x, y))
                                while x <= right, isFillable(x, y) { x += 1 }
                            } else {
                                x += 1
                            }
                        }
                    }
                }
            }
        }

        let touchesEdge = (0..<width).contains { mask[$0] == 255 || mask[(height - 1) * width + $0] == 255 }
            || (0..<height).contains { mask[$0 * width] == 255 || mask[$0 * width + width - 1] == 255 }

        self.width = width
        self.height = height
        fullPixels = mask
        hasEnclosedScreen = mask.contains(255) && !touchesEdge
    }

    /// The mask cropped to a rectangle, row by row.
    func croppedPixels(offset: CGPoint, size: CGSize) -> [UInt8] {
        var cropped = [UInt8]()
        cropped.reserveCapacity(Int(size.width * size.height))

        for y in Int(offset.y)..<Int(offset.y + size.height) {
            let start = y * width + Int(offset.x)
            cropped.append(contentsOf: fullPixels[start..<(start + Int(size.width))])
        }

        return cropped
    }
}

/// Renders an image upright into 8-bit premultiplied RGBA. Drawing a `UIImage` honors its orientation,
/// so frames stored sideways with an orientation tag come out the way they are displayed.
private func rgbaPixels(of image: UIImage) -> [UInt8] {
    let width = Int(image.size.width)
    let height = Int(image.size.height)
    var pixels = [UInt8](repeating: 0, count: width * height * 4)

    pixels.withUnsafeMutableBytes { buffer in
        guard let context = CGContext(
            data: buffer.baseAddress,
            width: width,
            height: height,
            bitsPerComponent: 8,
            bytesPerRow: width * 4,
            space: CGColorSpaceCreateDeviceRGB(),
            bitmapInfo: CGImageAlphaInfo.premultipliedLast.rawValue
        ) else {
            return
        }

        // Flip into UIKit's top-left origin so row 0 is the top of the image.
        context.translateBy(x: 0, y: CGFloat(height))
        context.scaleBy(x: 1, y: -1)
        UIGraphicsPushContext(context)
        image.draw(in: CGRect(x: 0, y: 0, width: width, height: height))
        UIGraphicsPopContext()
    }

    return pixels
}
